class Map(SOp):
  """A Sequence Operation representing an elementwise map."""
  _ids = itertools.count(1)
  _name_cache = {}

  def __init__(self, f: Callable[[Value], Value], expr: SOp):
    super().__init__()
    self.f = f
    self.expr = expr

  @property
  def children(self) -> Sequence[RASPExpr]:
    return [self.expr]

  @property
  def name(self) -> str:
    """The name of this expression."""
    if name := self._name_cache.get(self.f):
      return name
    f_name = self._default_name_from_fn(self.f)
    expr_name = self.expr.name
    return f"{f_name}({expr_name})"

  def _default_name_from_fn(self, f: Callable[[Value], Value]) -> str:
    """Return a human-readable name for the given function."""
    if isinstance(f, functools.partial):
      f = f.func
    return getattr(f, "__name__", repr(f))

  def __call__(self, xs: Sequence[Value]) -> Sequence[Value]:
    return [self.f(x) for x in xs]

  def __repr__(self):
    return f"Map({self.f!r}, {self.expr!r})"


class SequenceMap(SOp):
  """A Sequence Operation representing an elementwise map of two sequences."""
  _ids = itertools.count(1)

  def __init__(self, f: Callable[[Value, Value], Value], expr1: SOp,
               expr2: SOp):
    super().__init__()
    self.f = f
    self.expr1 = expr1
    self.expr2 = expr2

  @property
  def children(self) -> Sequence[RASPExpr]:
    return [self.expr1, self.expr2]

  @property
  def name(self) -> str:
    """The name of this expression."""
    f_name = self._default_name_from_fn(self.f)
    return f"{f_name}({self.expr1.name}, {self.expr2.name})"

  def _default_name_from_fn(self, f: Callable[[Value, Value], Value]) -> str:
    """Return a human-readable name for the given function."""
    if isinstance(f, functools.partial):
      f = f.func
    return getattr(f, "__name__", repr(f))

  def __call__(self, xs: Sequence[Value]) -> Sequence[Value]:
    return [self.f(x, y) for x, y in zip(xs, self.expr2(xs))]

  def __repr__(self):
    return f"SequenceMap({self.f!r}, {self.expr1!r}, {self.expr2!r})"

