def selector_and(sel1: Selector, sel2: Selector) -> Selector:
  """Creates a new Selector that returns the intersection of two Selectors."""
  return SelectAggregate(
      lambda x, y: x and y,
      sel1,
      sel2,
  )


def selector_or(sel1: Selector, sel2: Selector) -> Selector:
  """Creates a new Selector that returns the union of two Selectors."""
  return SelectAggregate(
      lambda x, y: x or y,
      sel1,
      sel2,
  )


def selector_not(sel: Selector) -> Selector:
  """Creates a new Selector that returns the complement of a Selector."""
  return SelectAggregate(
      lambda x: not x,
      sel,
  )


