class SelectAggregate(Selector):
  """Selector that combines the output of multiple Selectors.

  In general SelectAggregate aggregates all values from all input selectors
  using a reduction function and returns the result. For most use cases, this
  will be a boolean operation like and or or, and the result is a selector.
  """

  reduce_fn: Callable[..., SelectorValue]
  selectors: Sequence[Selector]

