def construct_optimizer(
    model: torch.nn.Module,
    optimizer_conf: DictConfig,
) -> torch.optim.Optimizer:
    """
    Constructs a stochastic gradient descent or ADAM (or ADAMw) optimizer
    with momentum. i.e, constructs a single param_groups, all params have
    the same momentum, learning rate, weight decay, etc.

    Args:
        model (torch.nn.Module): model to be optimized
        optimizer_conf (DictConfig): configurations for the optimizer

    Returns:
        optim (torch.optim.Optimizer): the constructed optimizer
    """
    if optimizer_conf.optimizer == "adamw":
        optimizer = torch.optim.AdamW
    elif optimizer_conf.optimizer == "adam":
        optimizer = torch.optim.Adam
    elif optimizer_conf.optimizer == "sgd":
        optimizer = torch.optim.SGD
    else:
        raise NotImplementedError(
            f"Does not support optimizer: {optimizer_conf.optimizer}"
        )

    if optimizer_conf.param_group_scheduler is None:
        return optimizer(
            model.parameters(),
            lr=optimizer_conf.lr,
            weight_decay=optimizer_conf.weight_decay,
            **optimizer_conf.optimizer_params,
        )

    scheduler_cfgs_per_param_group = []
    for scheduler_cfg in optimizer_conf.param_group_scheduler:
        scheduler_cfg = DictConfig(scheduler_cfg)
        scheduler_cfg.parameter_names = unix_pattern_to_parameter_names(
            scheduler_cfg, model
        )
        scheduler_cfgs_per_param_group.append(scheduler_cfg)

    all_parameter_names = {name for name, _ in model.named_parameters()}
    set_default_parameters(scheduler_cfgs_per_param_group, all_parameter_names)

    schedulers, param_groups = map_scheduler_cfgs_to_param_groups(
        scheduler_cfgs_per_param_group, model
    )
    validate_param_group_params(param_groups, model)

    for param_group, scheduler in zip(param_groups, schedulers):
        param_group.update(scheduler)

    return optimizer(
        param_groups,
        lr=optimizer_conf.lr,
        weight_decay=optimizer_conf.weight_decay,
        **optimizer_conf.optimizer_params,
    )

