@jax.jit
def _budget_constraint(media: jnp.ndarray,
                       prices: jnp.ndarray,
                       budget: Union[float, jnp.ndarray]) -> jnp.float64:
  """Calculates the budget constraint of the media plan.

  Args:
    media: Media values for which to calculate the budget constraint.
    prices: Prices of each media channel.
    budget: Total budget to be spent.

  Returns:
    The difference between the budget and the cost of the media plan.
  """
  return budget - jnp.sum(media * prices)


