# dataset, dataloader, collator

class Collator:
    def __init__(self, image_size, url_label, text_label, image_label, name, channels):
        self.url_label = url_label
        self.text_label = text_label
        self.image_label = image_label
        self.download = url_label is not None
        self.name = name
        self.channels = channels
        self.transform = T.Compose([
            T.Resize(image_size),
            T.CenterCrop(image_size),
            T.ToTensor(),
        ])
    def __call__(self, batch):

        texts = []
        images = []
        for item in batch:
            try:
                if self.download:
                    image = fetch_image(item)
                else:
                    image = item[self.image_label]

                image = convert_image_to('RGB', image)
                image = self.transform(image)
                image = image[:self.channels]

                text = item[self.text_label]
                if isinstance(text, list):
                    text = random.choice(text)

                texts.append(text)
                images.append(image)
            except Exception as e:
                continue

        text_inputs = t5.t5_tokenize(texts)
        text_embeds = t5.t5_encode_tokenized_text(*text_inputs)
        text_mask = torch.any(text_inputs[1].bool(), dim = -1)

        if exists(self.image_label):
            images = torch.stack(images)

        return texts, text_embeds, text_mask, images

def fetch_image(item):
    image = None
    for _ in range(5):
        try:
            url = item['url']
            image = Image.open(urllib.request.urlopen(urllib.request.Request(url, headers = {'User-Agent': USER_AGENT})))
            break
        except Exception as e:
            continue
    return image

