def split_args_and_kwargs(*args, split_size = None, **kwargs):
    all_args = (*args, *kwargs.values())
    len_all_args = len(all_args)
    first_tensor = find_first(lambda t: isinstance(t, torch.Tensor), all_args)
    assert exists(first_tensor)

    batch_size = len(all_args[first_tensor])
    split_size = default(split_size, batch_size)
    num_chunks = ceil(batch_size / split_size)

    chunk_len = num_chunks
    chunk_size = ceil(batch_size / num_chunks)

    split_args = tuple(map(lambda t: split(t, split_size = chunk_size), args))
    split_kwargs = tuple(map(lambda t: split(t, split_size = chunk_size), kwargs.values()))

    split_args_and_kwargs = (*split_args, *split_kwargs)
    split_args_and_kwargs = tuple(zip(*split_args_and_kwargs))

    return split_args_and_kwargs

def create_optimizer(model, lr, wd, betas, use_lion = False):
    if use_lion:
        return Lion(model.parameters(), lr = lr, weight_decay = wd, betas = betas)

    return Adam(model.parameters(), lr = lr, weight_decay = wd, betas = betas)

def create_lr_scheduler(optimizer, num_steps, warmup_steps = None, cosine_decay = True):
    warmup_steps = default(warmup_steps, 0)

    def lr_lambda(step):
        if step < warmup_steps:
            return step / warmup_steps

        if not cosine_decay:
            return 1.

        progress = (step - warmup_steps) / (num_steps - warmup_steps)
        return max(0., 0.5 * (1. + np.cos(np.pi * progress)))

    return LambdaLR(optimizer, lr_lambda)

def get_lr(optimizer):
    for param_group in optimizer.param_groups:
        return param_group['lr']

def set_lr(optimizer, lr):
    for param_group in optimizer.param_groups:
        param_group['lr'] = lr

def save_checkpoint(path, model, optimizer, scheduler, scaler, step, **kwargs):
    path = Path(path)
    path.parent.mkdir(exist_ok = True, parents = True)

    save_obj = dict(
        model = model.state_dict(),
        optimizer = optimizer.state_dict(),
        scheduler = scheduler.state_dict() if exists(scheduler) else None,
        scaler = scaler.state_dict() if exists(scaler) else None,
        step = step,
        version = __version__,
        **kwargs
    )

    torch.save(save_obj, str(path))

def load_checkpoint(path, model, optimizer = None, scheduler = None, scaler = None, strict = True):
    path = Path(path)
    assert path.exists(), f'checkpoint path {str(path)} does not exist'

    save_obj = torch.load(str(path), map_location = 'cpu')

    model.load_state_dict(save_obj['model'], strict = strict)

    if exists(optimizer) and exists(save_obj.get('optimizer')):
        optimizer.load_state_dict(save_obj['optimizer'])

    if exists(scheduler) and exists(save_obj.get('scheduler')):
        scheduler.load_state_dict(save_obj['scheduler'])

    if exists(scaler) and exists(save_obj.get('scaler')):
        scaler.load_state_dict(save_obj['scaler'])

    return save_obj.get('step', 0)

